const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Polygon([
      [-93.0, 41.0],
      [-93.0, 49.8],
      [-74.0, 49.8],
      [-74.0, 41.0]
    ]);
    const targetDates = [
      { label: '2021-02-20', date: ee.Date('2021-02-20') },
      { label: '2021-03-03', date: ee.Date('2021-03-03') }
    ];
    const searchWindows = [2, 5, 8, 12]; // days around target date

    // 2. Water mask from JRC Global Surface Water (permanent water)
    const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater');
    const waterMask = gsw.select('occurrence').gt(50).selfMask().clip(region);
    const areaKm2 = ee.Image.pixelArea().divide(1e6).rename('area');

    // Helpers
    function getInfoAsync(eeObj) {
      return new Promise((resolve, reject) => {
        eeObj.getInfo((res, err) => {
          if (err) reject(err);
          else resolve(res);
        });
      });
    }

    async function getS1Composite(date) {
      for (let i = 0; i < searchWindows.length; i++) {
        const w = searchWindows[i];
        const start = date.advance(-w, 'day');
        const end = date.advance(w + 1, 'day'); // end exclusive
        let col = ee.ImageCollection('COPERNICUS/S1_GRD')
          .filterBounds(region)
          .filterDate(start, end)
          .filter(ee.Filter.eq('instrumentMode', 'IW'))
          .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
          .filter(ee.Filter.eq('resolution_meters', 10))
          .select(['VV']);
        const size = await getInfoAsync(col.size());
        if (size > 0) {
          // Median composite, convert to dB
          const median = col.median();
          const vvLin = median.select('VV').max(1e-6);
          const vvDb = vvLin.log10().multiply(10).rename('VV_dB').clip(region);
          return { image: vvDb, images: size, window: w };
        }
      }
      return null;
    }

    // 3. Acquire S1 composites for both dates (fallback to MODIS if needed)
    const results = [];
    let s1Failed = false;
    for (const td of targetDates) {
      const comp = await getS1Composite(td.date);
      if (!comp) {
        s1Failed = true;
        break;
      }
      results.push({ label: td.label, ...comp });
    }

    // Fallback to MODIS Snow Cover if S1 failed for any date
    async function getMODISComposite(date) {
      for (let i = 0; i < searchWindows.length; i++) {
        const w = searchWindows[i];
        const start = date.advance(-w, 'day');
        const end = date.advance(w + 1, 'day');
        let col = ee.ImageCollection('MODIS/061/MOD10A1')
          .filterBounds(region)
          .filterDate(start, end)
          .select(['NDSI_Snow_Cover']);
        const size = await getInfoAsync(col.size());
        if (size > 0) {
          // Valid values: 0-100; mask out >100 (clouds/others)
          const snowPct = col.median().rename('NDSI_Snow_Cover').clip(region);
          const valid = snowPct.lte(100);
          const snowOnWater = snowPct.updateMask(valid).gt(10); // >10% snow
          return { image: snowOnWater.rename('ICE_BIN'), images: size, window: w, isBinary: true };
        }
      }
      return null;
    }

    let usingMODIS = false;
    if (s1Failed) {
      // Try MODIS for both dates
      results.length = 0;
      for (const td of targetDates) {
        const comp = await getMODISComposite(td.date);
        if (!comp) {
          console.log('One or both periods have no images after fallback (S1+MODIS).');
          console.log('C1: Empty Collection');
          return;
        }
        results.push({ label: td.label, ...comp });
      }
      usingMODIS = true;
    }

    // 4. Ice classification and area computation
    // For S1 use fixed threshold on VV_dB; For MODIS, image is already binary "ICE_BIN".
    const thresholdDb = -17; // dB threshold: higher backscatter -> ice
    const outputs = [];
    for (const r of results) {
      let iceBin;
      let validWaterMask;
      if (usingMODIS) {
        iceBin = r.image.updateMask(waterMask); // already binary
        validWaterMask = waterMask.updateMask(r.image.mask());
      } else {
        const vv = r.image; // VV_dB
        validWaterMask = waterMask.updateMask(vv.mask());
        iceBin = vv.gt(thresholdDb).updateMask(validWaterMask);
      }

      // Compute areas
      const waterAreaDict = await getInfoAsync(areaKm2.updateMask(validWaterMask)
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e13
        }));
      const iceAreaDict = await getInfoAsync(areaKm2.updateMask(iceBin)
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e13
        }));

      const waterArea = waterAreaDict ? waterAreaDict.area : null;
      const iceArea = iceAreaDict ? iceAreaDict.area : null;

      if (waterArea === null || iceArea === null) {
        console.log(`Calculation failure for ${r.label}.`);
        console.log('C3: Calculation Failure');
        return;
      }
      if (!isFinite(waterArea) || !isFinite(iceArea) || waterArea <= 0) {
        console.log(`No valid pixels after masking for ${r.label}.`);
        console.log('C2: No Valid Pixels');
        return;
      }

      const icePct = (iceArea / waterArea) * 100;
      if (!isFinite(icePct) || icePct < 0 || icePct > 100) {
        console.log(`Invalid ice% (${icePct}) for ${r.label}.`);
        console.log('C3: Calculation Failure');
        return;
      }

      outputs.push({
        label: r.label,
        images: r.images,
        window: r.window,
        waterArea: waterArea,
        iceArea: iceArea,
        icePct: icePct
      });
    }

    // 5. Print concise summary (<= 20 lines) and final answer
    if (!usingMODIS) {
      console.log(`Sensor: Sentinel-1 SAR (cloud%: NA) | Threshold dB: ${thresholdDb}`);
    } else {
      console.log('Sensor: MODIS Snow (cloud-masked by value<=100)');
    }
    for (const o of outputs) {
      console.log(`${o.label} Images: ${o.images} (±${o.window}d)`);
      console.log(`${o.label} Water(km^2): ${o.waterArea.toFixed(0)}, Ice(km^2): ${o.iceArea.toFixed(0)}, Ice%: ${o.icePct.toFixed(1)}`);
    }

    const early = outputs[0].icePct;
    const later = outputs[1].icePct;
    const delta = later - early;
    console.log(`Δ Ice% (Mar 3 - Feb 20): ${delta.toFixed(1)}`);

    if (later < early) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
